const raw = $input.first().json || {};
const query = (raw.query || '').trim();
const topK = Math.min(parseInt(raw.top_k, 10) || 5, 10);
const vendor = (raw.vendor || '').trim();
if (!query) {
  return [{ json: { error: 'query es requerido', skip: true } }];
}
return [{ json: { query, topK, vendor } }];

const emb = $json.embedding;
if (!Array.isArray(emb) || emb.length !== 768) {
  return [{ json: { error: `embedding inválido (len=${emb ? emb.length : 0})`, skip: true } }];
}
const literal = '[' + emb.join(',') + ']';
const orig = $('Normalize Input').first().json;
return [{ json: { vector_literal: literal, topK: orig.topK, vendor: orig.vendor, query: orig.query } }];

const rows = $input.all().map(i => i.json);
const input = $('Normalize Input').first().json;
if (!rows.length) {
  return [{ json: { found: false, message: `Sin documentos relevantes para '${input.query}'.`, query: input.query } }];
}
return [{ json: {
  found: true,
  count: rows.length,
  query: input.query,
  results: rows.map(r => ({
    similarity: Number(r.similarity).toFixed(3),
    vendor: r.vendor,
    title: r.title,
    category: r.category_hint,
    url: r.source_url,
    text: r.chunk_text.substring(0, 500)
  }))
} }];
